{"security_risk":"LOW","summary":"Create protocol.rs","command":"create","path":"/workspace/codebase/src/protocol.rs","file_text":"//! JSON-over-stdio protocol shared between the Rust CLI and the Node.js
//! transform worker.
//!
//! Messages are line-delimited JSON. The Rust process owns the worker
//! lifecycle and pushes commands; the worker emits status updates back
//! as transforms complete.

use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SetupMessage {
    pub action: String,
    pub transform: String,
    pub babel: bool,
    pub parser: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub parser_config: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub extensions: Option<Vec<String>>,
    pub transform_options: serde_json::Value,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub transform_options_arg: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub additional_options: Option<serde_json::Value>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct TransformMessage {
    pub action: String,
    pub path: String,
    pub source: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct FinishMessage {
    pub action: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "action", rename_all = "snake_case")]
pub enum WorkerToRunner {
    /// Worker reports a file's outcome. Mirrors the status codes emitted by
    /// the upstream jscodeshift worker (`ok|skip|error`).
    Status {
        status: String,
        msg: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        path: Option<String>,
    },
    /// Periodic progress update (`update`).
    Update {
        name: String,
        quantity: usize,
    },
    /// Worker is ready to receive the next transform message.
    Free,
    /// A log line from the worker that should be forwarded to the user.
    Log {
        level: String,
        msg: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        path: Option<String>,
    },
    /// Worker crashed or exited unexpectedly.
    Died {
        msg: String,
    },
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "action", rename_all = "snake_case")]
pub enum RunnerToWorker {
    Setup(SetupMessage),
    Transform(TransformMessage),
    Finish(FinishMessage),
}"}

{"security_risk":"LOW","summary":"Create ignore.rs","command":"create","path":"/workspace/codebase/src/ignore.rs","file_text":"//! Gitignore-style ignore-rule matching.
//!
//! The rules are equivalent to the previous `picomatch`-based implementation
//! in `src/ignoreFiles.js`. We translate the patterns into `globset`
//! matchers and additionally mirror the upstream normalization that strips
//! a leading `./` or `../` traversal segment, so callers can pass paths
//! expressed with relative traversal prefixes without surprising misses.

use std::fs;
use std::path::Path;

use globset::{GlobBuilder, GlobMatcher};

#[derive(Default)]
pub struct IgnoreSet {
    matchers: Vec<GlobMatcher>,
}

impl IgnoreSet {
    pub fn new() -> Self {
        Self::default()
    }

    /// Add one or more gitignore-style patterns.
    pub fn add<I, S>(&mut self, patterns: I)
    where
        I: IntoIterator<Item = S>,
        S: AsRef<str>,
    {
        for raw in patterns {
            self.add_one(raw.as_ref());
        }
    }

    /// Read patterns from one or more gitignore-style files.
    pub fn add_from_files<I, P>(&mut self, files: I) -> std::io::Result<()>
    where
        I: IntoIterator<Item = P>,
        P: AsRef<Path>,
    {
        for file in files {
            let path = file.as_ref();
            let meta = fs::metadata(path)?;
            if meta.is_file() {
                let content = fs::read_to_string(path)?;
                for line in content.lines() {
                    self.add_one(line);
                }
            }
        }
        Ok(())
    }

    pub fn should_ignore<P: AsRef<Path>>(&self, path: P) -> bool {
        if self.matchers.is_empty() {
            return false;
        }
        let path_str = path.as_ref().to_string_lossy().to_string();
        if self.matches(&path_str) {
            return true;
        }
        // Mirror the upstream normalization: strip a leading traversal
        // prefix (`./`, `../`, `.\`, `..\`) so patterns with `**` match the
        // path regardless of how the caller spelled it.
        let normalized = strip_traversal_prefix(&path_str);
        if normalized != path_str && self.matches(&normalized) {
            return true;
        }
        false
    }

    fn matches(&self, path_str: &str) -> bool {
        // globset's `is_match` uses forward slashes on all platforms; emulate
        // that by trying both the original and the OS-normalized variants.
        if self.matchers.iter().any(|m| m.is_match(path_str)) {
            return true;
        }
        let alt = path_str.replace('\\', "/");
        if alt != path_str && self.matchers.iter().any(|m| m.is_match(&alt)) {
            return true;
        }
        false
    }

    fn add_one(&mut self, val: &str) {
        let trimmed = val.trim_end();
        if trimmed.is_empty() || trimmed.starts_with('#') {
            return;
        }
        let pattern = trimmed;
        if !pattern.contains('/') {
            self.push_pattern(&format!("**/{}", pattern));
        } else if pattern.ends_with('/') {
            self.push_pattern(&format!("**/{}**", pattern));
            self.push_pattern(&format!("{}**", pattern));
        }
        self.push_pattern(pattern);
    }

    fn push_pattern(&mut self, pattern: &str) {
        if let Ok(glob) = GlobBuilder::new(pattern)
            .literal_separator(false)
            .build()
        {
            self.matchers.push(glob.compile_matcher());
        }
    }
}

fn strip_traversal_prefix(path: &str) -> String {
    let mut chars = path.chars().peekable();
    loop {
        let prefix: String = chars.clone().take(3).collect();
        if prefix == "./" || prefix == ".\\" {
            for _ in 0..2 {
                chars.next();
            }
            continue;
        }
        let prefix: String = chars.clone().take(4).collect();
        if prefix == "../" || prefix == "..\\" {
            for _ in 0..3 {
                chars.next();
            }
            continue;
        }
        break;
    }
    chars.collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn matches_node_modules() {
        let mut ig = IgnoreSet::new();
        ig.add(["node_modules".to_string()]);
        assert!(ig.should_ignore("src/node_modules/foo.js"));
        assert!(ig.should_ignore("node_modules/foo.js"));
        assert!(!ig.should_ignore("src/foo.js"));
    }

    #[test]
    fn matches_traversal_prefix() {
        let mut ig = IgnoreSet::new();
        ig.add(["**/dist".to_string()]);
        assert!(ig.should_ignore("./dist"));
        assert!(ig.should_ignore("../dist"));
        assert!(ig.should_ignore("dist"));
    }

    #[test]
    fn blank_and_comments_skipped() {
        let mut ig = IgnoreSet::new();
        ig.add(["# comment", "", "  "]);
        assert!(!ig.should_ignore("anything"));
    }
}"}

