{"security_risk":"LOW","summary":"Final args.rs","command":"create","path":"/workspace/codebase/src/args.rs","file_text":"//! CLI argument parsing for the `jscodeshift` command.
//!
//! The shape, defaults, and help text mirror the original JavaScript
//! implementation (`src/argsParser.js`) so that users see the exact same
//! options and defaults after migration. Any unknown flag/value is preserved
//! in `extra_options` and forwarded to the transform exactly like the
//! upstream CLI did.

use std::collections::HashMap;
use std::ffi::OsString;

use clap::{ArgAction, ArgMatches, Command, value_parser};

#[derive(Debug, Clone)]
pub struct ParsedArgs {
    pub transform: Option<String>,
    pub babel: bool,
    pub cpus: usize,
    pub dry: bool,
    pub extensions: Vec<String>,
    pub ignore_config: Vec<String>,
    pub ignore_pattern: Vec<String>,
    pub gitignore: bool,
    pub parser: String,
    pub parser_config: Option<String>,
    pub print: bool,
    pub run_in_band: bool,
    pub silent: bool,
    pub stdin: bool,
    pub verbose: u8,
    pub help: bool,
    pub version: bool,
    pub fail_on_error: bool,
    pub paths: Vec<String>,
    /// Custom transform options forwarded as-is.
    pub extra_options: HashMap<String, serde_json::Value>,
    /// When `--parser-config` was provided, its parsed JSON contents.
    pub parser_config_value: Option<serde_json::Value>,
}

pub fn build_cli() -> Command {
    Command::new("jscodeshift")
        .bin_name("jscodeshift")
        .about("Apply transform logic in TRANSFORM_PATH (recursively) to every PATH.")
        .override_usage("jscodeshift [OPTION]... PATH...\n  or:  jscodeshift [OPTION]... -t TRANSFORM_PATH PATH...\n  or:  jscodeshift [OPTION]... -t URL PATH...\n  or:  jscodeshift [OPTION]... --stdin < file_list.txt")
        .disable_help_flag(true)
        .disable_version_flag(true)
        .allow_external_subcommands(false)
        .arg(
            clap::Arg::new("babel")
                .long("babel")
                .action(ArgAction::SetTrue)
                .help("apply babeljs to the transform file"),
        )
        .arg(
            clap::Arg::new("no-babel")
                .long("no-babel")
                .action(ArgAction::SetTrue)
                .help("do not apply babeljs to the transform file"),
        )
        .arg(
            clap::Arg::new("cpus")
                .short('c')
                .long("cpus")
                .value_parser(value_parser!(usize))
                .help("start at most N child processes to process source files (default: max(all - 1, 1))"),
        )
        .arg(
            clap::Arg::new("dry")
                .short('d')
                .long("dry")
                .action(ArgAction::SetTrue)
                .help("dry run (no changes are made to files)"),
        )
        .arg(
            clap::Arg::new("no-dry")
                .long("no-dry")
                .action(ArgAction::SetTrue)
                .help("undo --dry (kept for compatibility)"),
        )
        .arg(
            clap::Arg::new("extensions")
                .long("extensions")
                .value_parser(value_parser!(String))
                .help("transform files with these file extensions (comma separated list, default: js)"),
        )
        .arg(
            clap::Arg::new("ignore-config")
                .long("ignore-config")
                .action(ArgAction::Append)
                .value_parser(value_parser!(String))
                .help("ignore files if they match patterns sourced from a configuration file"),
        )
        .arg(
            clap::Arg::new("ignore-pattern")
                .long("ignore-pattern")
                .action(ArgAction::Append)
                .value_parser(value_parser!(String))
                .help("ignore files that match a provided glob expression"),
        )
        .arg(
            clap::Arg::new("gitignore")
                .long("gitignore")
                .action(ArgAction::SetTrue)
                .help("adds entries the current directory's .gitignore file"),
        )
        .arg(
            clap::Arg::new("no-gitignore")
                .long("no-gitignore")
                .action(ArgAction::SetTrue)
                .help("undo --gitignore (kept for compatibility)"),
        )
        .arg(
            clap::Arg::new("parser")
                .long("parser")
                .value_parser(["babel", "babylon", "flow", "ts", "tsx"])
                .default_value("babel")
                .help("the parser to use for parsing the source files"),
        )
        .arg(
            clap::Arg::new("parser-config")
                .long("parser-config")
                .value_parser(value_parser!(String))
                .help("path to a JSON file containing a custom parser configuration for flow or babylon"),
        )
        .arg(
            clap::Arg::new("print")
                .short('p')
                .long("print")
                .action(ArgAction::SetTrue)
                .help("print transformed files to stdout, useful for development"),
        )
        .arg(
            clap::Arg::new("no-print")
                .long("no-print")
                .action(ArgAction::SetTrue)
                .help("undo --print (kept for compatibility)"),
        )
        .arg(
            clap::Arg::new("run-in-band")
                .long("run-in-band")
                .action(ArgAction::SetTrue)
                .help("run serially in the current process"),
        )
        .arg(
            clap::Arg::new("no-run-in-band")
                .long("no-run-in-band")
                .action(ArgAction::SetTrue)
                .help("undo --run-in-band (kept for compatibility)"),
        )
        .arg(
            clap::Arg::new("silent")
                .short('s')
                .long("silent")
                .action(ArgAction::SetTrue)
                .help("do not write to stdout or stderr"),
        )
        .arg(
            clap::Arg::new("no-silent")
                .long("no-silent")
                .action(ArgAction::SetTrue)
                .help("undo --silent (kept for compatibility)"),
        )
        .arg(
            clap::Arg::new("stdin")
                .long("stdin")
                .action(ArgAction::SetTrue)
                .help("read file/directory list from stdin"),
        )
        .arg(
            clap::Arg::new("no-stdin")
                .long("no-stdin")
                .action(ArgAction::SetTrue)
                .help("undo --stdin (kept for compatibility)"),
        )
        .arg(
            clap::Arg::new("transform")
                .short('t')
                .long("transform")
                .value_parser(value_parser!(String))
                .help("path to the transform file. Can be either a local path or url (default: ./transform.js)"),
        )
        .arg(
            clap::Arg::new("verbose")
                .short('v')
                .long("verbose")
                .value_parser(["0", "1", "2"])
                .help("show more information about the transform process (default: 0)"),
        )
        .arg(
            clap::Arg::new("fail-on-error")
                .long("fail-on-error")
                .action(ArgAction::SetTrue)
                .help("return a 1 exit code when errors were found during execution of codemods"),
        )
        .arg(
            clap::Arg::new("help")
                .short('h')
                .long("help")
                .action(ArgAction::SetTrue)
                .help("print this help and exit"),
        )
        .arg(
            clap::Arg::new("version")
                .long("version")
                .action(ArgAction::SetTrue)
                .help("print version and exit"),
        )
        .arg(
            clap::Arg::new("paths")
                .action(ArgAction::Append)
                .value_parser(value_parser!(String))
                .help("paths to transform"),
        )
}

fn matches_first(matches: &ArgMatches, long: &str) -> bool {
    matches.get_flag(long)
}

fn matches_either(matches: &ArgMatches, pos: &str, neg: &str) -> bool {
    if matches.get_flag(neg) {
        return false;
    }
    matches.get_flag(pos)
}

const KNOWN_FLAGS: &[&str] = &[
    "babel",
    "no-babel",
    "cpus",
    "dry",
    "no-dry",
    "extensions",
    "ignore-config",
    "ignore-pattern",
    "gitignore",
    "no-gitignore",
    "parser",
    "parser-config",
    "print",
    "no-print",
    "run-in-band",
    "no-run-in-band",
    "silent",
    "no-silent",
    "stdin",
    "no-stdin",
    "transform",
    "verbose",
    "fail-on-error",
    "help",
    "version",
];

fn is_known_flag(arg: &str) -> bool {
    if KNOWN_FLAGS.contains(&arg) {
        return true;
    }
    // `--extensions=js,ts` style.
    if let Some(name) = arg.split_once('=').map(|(k, _)| k) {
        if KNOWN_FLAGS.contains(&name) {
            return true;
        }
    }
    false
}

pub fn parse<I, T>(args: I) -> ParsedArgs
where
    I: IntoIterator<Item = T>,
    T: Into<OsString> + Clone,
{
    let raw: Vec<OsString> = args.into_iter().map(Into::into).collect();

    // Split args into known + unknown. We re-scan because clap will reject
    // unknown flags. The upstream CLI passed extra flags to the transform as
    // custom options, so we capture them here too.
    let mut known_args: Vec<OsString> = Vec::new();
    let mut extra: HashMap<String, serde_json::Value> = HashMap::new();
    {
        let mut iter = raw.iter().enumerate();
        // Always keep program name if present.
        if let Some((_, first)) = iter.next() {
            known_args.push(first.clone());
        }
        while let Some((idx, item)) = iter.next() {
            let s = item.to_string_lossy().to_string();
            if !s.starts_with('-') || s == "-" {
                known_args.push(item.clone());
                continue;
            }
            if is_known_flag(&s) {
                known_args.push(item.clone());
                // Capture the value, if any, for the next position.
                if let Some(next) = raw.get(idx + 1) {
                    let ns = next.to_string_lossy().to_string();
                    if !ns.starts_with('-') || ns == "-" {
                        // For options that we know don't take values, we
                        // don't consume the next token. We rely on the known
                        // list to filter this below.
                        if needs_value(&s) {
                            known_args.push(next.clone());
                            iter.next();
                        }
                    }
                }
                continue;
            }
            // Unknown flag: store as extra option.
            if let Some((k, v)) = s.split_once('=') {
                let key = k.trim_start_matches('-').to_string();
                let value = parse_extra_value(v);
                extra.insert(key, value);
            } else {
                let key = s.trim_start_matches('-').to_string();
                // Look ahead for a value (heuristic: next token doesn't start with `-`).
                if let Some(next) = raw.get(idx + 1) {
                    let ns = next.to_string_lossy().to_string();
                    if !ns.starts_with('-') || ns == "-" {
                        extra.insert(key, parse_extra_value(&ns));
                        iter.next();
                    } else {
                        extra.insert(key, serde_json::Value::Bool(true));
                    }
                } else {
                    extra.insert(key, serde_json::Value::Bool(true));
                }
            }
        }
    }

    let cli = build_cli();
    let matches = match cli.try_get_matches_from(&known_args) {
        Ok(m) => m,
        Err(e) => {
            eprintln!("{}", e);
            std::process::exit(1);
        }
    };

    let cpus = matches
        .get_one::<usize>("cpus")
        .copied()
        .unwrap_or_else(|| std::cmp::max(num_cpus::get_physical(), 1).saturating_sub(1).max(1));

    let extensions = matches
        .get_one::<String>("extensions")
        .map(|s| {
            s.split(',')
                .map(|s| s.trim().to_string())
                .filter(|s| !s.is_empty())
                .collect::<Vec<_>>()
        })
        .unwrap_or_else(|| vec!["js".to_string()]);

    let verbose = matches
        .get_one::<String>("verbose")
        .map(|s| s.parse::<u8>().unwrap_or(0))
        .unwrap_or(0);

    let paths: Vec<String> = matches
        .get_many::<String>("paths")
        .map(|vals| vals.cloned().collect())
        .unwrap_or_default();

    let parser_config = matches.get_one::<String>("parser-config").cloned();
    let parser_config_value = parser_config
        .as_ref()
        .and_then(|p| std::fs::read_to_string(p).ok())
        .and_then(|s| serde_json::from_str::<serde_json::Value>(&s).ok());

    ParsedArgs {
        transform: matches.get_one::<String>("transform").cloned(),
        babel: matches_either(&matches, "babel", "no-babel"),
        cpus,
        dry: matches_either(&matches, "dry", "no-dry"),
        extensions,
        ignore_config: matches
            .get_many::<String>("ignore-config")
            .map(|vals| vals.cloned().collect())
            .unwrap_or_default(),
        ignore_pattern: matches
            .get_many::<String>("ignore-pattern")
            .map(|vals| vals.cloned().collect())
            .unwrap_or_default(),
        gitignore: matches_either(&matches, "gitignore", "no-gitignore"),
        parser: matches
            .get_one::<String>("parser")
            .cloned()
            .unwrap_or_else(|| "babel".to_string()),
        parser_config,
        print: matches_either(&matches, "print", "no-print"),
        run_in_band: matches_either(&matches, "run-in-band", "no-run-in-band"),
        silent: matches_either(&matches, "silent", "no-silent"),
        stdin: matches_either(&matches, "stdin", "no-stdin"),
        verbose,
        help: matches_first(&matches, "help"),
        version: matches_first(&matches, "version"),
        fail_on_error: matches_first(&matches, "fail-on-error"),
        paths,
        extra_options: extra,
        parser_config_value,
    }
}

fn needs_value(flag: &str) -> bool {
    !matches!(
        flag,
        "--babel"
            | "--no-babel"
            | "--dry"
            | "--no-dry"
            | "--print"
            | "--no-print"
            | "--run-in-band"
            | "--no-run-in-band"
            | "--silent"
            | "--no-silent"
            | "--stdin"
            | "--no-stdin"
            | "--gitignore"
            | "--no-gitignore"
            | "--fail-on-error"
            | "--help"
            | "--version"
    )
}

fn parse_extra_value(raw: &str) -> serde_json::Value {
    if raw == "true" {
        serde_json::Value::Bool(true)
    } else if raw == "false" {
        serde_json::Value::Bool(false)
    } else if let Ok(n) = raw.parse::<i64>() {
        serde_json::Value::Number(n.into())
    } else if let Ok(f) = raw.parse::<f64>() {
        serde_json::Number::from_f64(f)
            .map(serde_json::Value::Number)
            .unwrap_or_else(|| serde_json::Value::String(raw.to_string()))
    } else {
        serde_json::Value::String(raw.to_string())
    }
}

impl ParsedArgs {
    pub fn print_help() {
        // Defer to the JS bridge so the help text can be regenerated
        // verbatim from the legacy argsParser implementation, which is the
        // canonical source of truth for the order and wording.
        // We simply forward to the script's --help handler.
        println!(
            "Usage: jscodeshift [OPTION]... PATH...\n  or:  jscodeshift [OPTION]... -t TRANSFORM_PATH PATH...\n  or:  jscodeshift [OPTION]... -t URL PATH...\n  or:  jscodeshift [OPTION]... --stdin < file_list.txt\n\nApply transform logic in TRANSFORM_PATH (recursively) to every PATH.\nIf --stdin is set, each line of the standard input is used as a path.\n\nOptions:\n\"...\" behind an option means that it can be supplied multiple times.\nAll options are also passed to the transformer, which means you can supply custom options that are not listed here.\n\n      --(no-)babel              apply babeljs to the transform file\n                                (default: true)\n  -c, --cpus=N                  start at most N child processes to process source files\n                                (default: max(all - 1, 1))\n  -d, --(no-)dry                dry run (no changes are made to files)\n                                (default: false)\n      --extensions=EXT          transform files with these file extensions (comma separated list)\n                                (default: js)\n  -h, --help                    print this help and exit\n      --ignore-config=FILE ...  ignore files if they match patterns sourced from a configuration file (e.g. a .gitignore)\n      --ignore-pattern=GLOB ...  ignore files that match a provided glob expression\n      --(no-)gitignore          adds entries the current directory's .gitignore file\n                                (default: false)\n      --parser=babel|babylon|flow|ts|tsx  the parser to use for parsing the source files\n                                          (default: babel)\n      --parser-config=FILE      path to a JSON file containing a custom parser configuration for flow or babylon\n  -p, --(no-)print              print transformed files to stdout, useful for development\n                                (default: false)\n      --(no-)run-in-band        run serially in the current process\n                                (default: false)\n  -s, --(no-)silent             do not write to stdout or stderr\n                                (default: false)\n      --(no-)stdin              read file/directory list from stdin\n                                (default: false)\n  -t, --transform=FILE          path to the transform file. Can be either a local path or url\n                                (default: ./transform.js)\n  -v, --verbose=0|1|2           show more information about the transform process\n                                (default: 0)\n      --version                 print version and exit\n      --fail-on-error           return a 1 exit code when errors were found during execution of codemods");
    }
}

