fn matches_first(matches: &ArgMatches, long: &str) -> bool {
    matches.get_flag(long)
}

fn matches_either(matches: &ArgMatches, pos: &str, neg: &str) -> bool {
    if matches.get_flag(neg) {
        return false;
    }
    matches.get_flag(pos)
}

const KNOWN_FLAGS: &[&str] = &[
    "babel",
    "no-babel",
    "cpus",
    "dry",
    "no-dry",
    "extensions",
    "ignore-config",
    "ignore-pattern",
    "gitignore",
    "no-gitignore",
    "parser",
    "parser-config",
    "print",
    "no-print",
    "run-in-band",
    "no-run-in-band",
    "silent",
    "no-silent",
    "stdin",
    "no-stdin",
    "transform",
    "verbose",
    "fail-on-error",
    "help",
    "version",
];

fn is_known_flag(arg: &str) -> bool {
    if KNOWN_FLAGS.contains(&arg) {
        return true;
    }
    if let Some(name) = arg.split_once('=').map(|(k, _)| k) {
        if KNOWN_FLAGS.contains(&name) {
            return true;
        }
    }
    false
}

pub fn parse<I, T>(args: I) -> ParsedArgs
where
    I: IntoIterator<Item = T>,
    T: Into<OsString> + Clone,
{
    let raw: Vec<OsString> = args.into_iter().map(Into::into).collect();

    let mut known_args: Vec<OsString> = Vec::new();
    let mut extra: HashMap<String, serde_json::Value> = HashMap::new();
    {
        let mut iter = raw.iter().enumerate();
        if let Some((_, first)) = iter.next() {
            known_args.push(first.clone());
        }
        while let Some((idx, item)) = iter.next() {
            let s = item.to_string_lossy().to_string();
            if !s.starts_with('-') || s == "-" {
                known_args.push(item.clone());
                continue;
            }
            if is_known_flag(&s) {
                known_args.push(item.clone());
                if needs_value(&s) {
                    if let Some(next) = raw.get(idx + 1) {
                        let ns = next.to_string_lossy().to_string();
                        if !ns.starts_with('-') || ns == "-" {
                            known_args.push(next.clone());
                            iter.next();
                        }
                    }
                }
                continue;
            }
            if let Some((k, v)) = s.split_once('=') {
                let key = k.trim_start_matches('-').to_string();
                extra.insert(key, parse_extra_value(v));
            } else {
                let key = s.trim_start_matches('-').to_string();
                if let Some(next) = raw.get(idx + 1) {
                    let ns = next.to_string_lossy().to_string();
                    if !ns.starts_with('-') || ns == "-" {
                        extra.insert(key, parse_extra_value(&ns));
                        iter.next();
                    } else {
                        extra.insert(key, serde_json::Value::Bool(true));
                    }
                } else {
                    extra.insert(key, serde_json::Value::Bool(true));
                }
            }
        }
    }

    let cli = build_cli();
    let matches = match cli.try_get_matches_from(&known_args) {
        Ok(m) => m,
        Err(e) => {
            eprintln!("{}", e);
            std::process::exit(1);
        }
    };

    let cpus = matches
        .get_one::<usize>("cpus")
        .copied()
        .unwrap_or_else(|| std::cmp::max(num_cpus::get_physical(), 1).saturating_sub(1).max(1));

    let extensions = matches
        .get_one::<String>("extensions")
        .map(|s| {
            s.split(',')
                .map(|s| s.trim().to_string())
                .filter(|s| !s.is_empty())
                .collect::<Vec<_>>()
        })
        .unwrap_or_else(|| vec!["js".to_string()]);

    let verbose = matches
        .get_one::<String>("verbose")
        .map(|s| s.parse::<u8>().unwrap_or(0))
        .unwrap_or(0);

    let paths: Vec<String> = matches
        .get_many::<String>("paths")
        .map(|vals| vals.cloned().collect())
        .unwrap_or_default();

    let parser_config = matches.get_one::<String>("parser-config").cloned();
    let parser_config_value = parser_config
        .as_ref()
        .and_then(|p| std::fs::read_to_string(p).ok())
        .and_then(|s| serde_json::from_str::<serde_json::Value>(&s).ok());

    ParsedArgs {
        transform: matches.get_one::<String>("transform").cloned(),
        babel: matches_either(&matches, "babel", "no-babel"),
        cpus,
        dry: matches_either(&matches, "dry", "no-dry"),
        extensions,
        ignore_config: matches
            .get_many::<String>("ignore-config")
            .map(|vals| vals.cloned().collect())
            .unwrap_or_default(),
        ignore_pattern: matches
            .get_many::<String>("ignore-pattern")
            .map(|vals| vals.cloned().collect())
            .unwrap_or_default(),
        gitignore: matches_either(&matches, "gitignore", "no-gitignore"),
        parser: matches
            .get_one::<String>("parser")
            .cloned()
            .unwrap_or_else(|| "babel".to_string()),
        parser_config,
        print: matches_either(&matches, "print", "no-print"),
        run_in_band: matches_either(&matches, "run-in-band", "no-run-in-band"),
        silent: matches_either(&matches, "silent", "no-silent"),
        stdin: matches_either(&matches, "stdin", "no-stdin"),
        verbose,
        help: matches_first(&matches, "help"),
        version: matches_first(&matches, "version"),
        fail_on_error: matches_first(&matches, "fail-on-error"),
        paths,
        extra_options: extra,
        parser_config_value,
    }
}

fn needs_value(flag: &str) -> bool {
    !matches!(
        flag,
        "--babel"
            | "--no-babel"
            | "--dry"
            | "--no-dry"
            | "--print"
            | "--no-print"
            | "--run-in-band"
            | "--no-run-in-band"
            | "--silent"
            | "--no-silent"
            | "--stdin"
            | "--no-stdin"
            | "--gitignore"
            | "--no-gitignore"
            | "--fail-on-error"
            | "--help"
            | "--version"
    )
}

fn parse_extra_value(raw: &str) -> serde_json::Value {
    if raw == "true" {
        serde_json::Value::Bool(true)
    } else if raw == "false" {
        serde_json::Value::Bool(false)
    } else if let Ok(n) = raw.parse::<i64>() {
        serde_json::Value::Number(n.into())
    } else if let Ok(f) = raw.parse::<f64>() {
        serde_json::Number::from_f64(f)
            .map(serde_json::Value::Number)
            .unwrap_or_else(|| serde_json::Value::String(raw.to_string()))
    } else {
        serde_json::Value::String(raw.to_string())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_basic_invocation() {
        let parsed = parse(["jscodeshift", "-t", "transform.js", "src"]);
        assert_eq!(parsed.transform.as_deref(), Some("transform.js"));
        assert_eq!(parsed.paths, vec!["src"]);
        assert!(parsed.babel);
        assert!(!parsed.dry);
    }

    #[test]
    fn parses_negative_flags() {
        let parsed = parse(["jscodeshift", "--no-babel", "--no-print", "-d", "src"]);
        assert!(!parsed.babel);
        assert!(!parsed.print);
        assert!(parsed.dry);
    }

    #[test]
    fn parses_extensions_csv() {
        let parsed = parse(["jscodeshift", "--extensions=ts,tsx,js", "src"]);
        assert_eq!(parsed.extensions, vec!["ts", "tsx", "js"]);
    }

    #[test]
    fn captures_extra_option() {
        let parsed = parse(["jscodeshift", "--my-flag=42", "src"]);
        assert_eq!(
            parsed.extra_options.get("my-flag"),
            Some(&serde_json::json!(42))
        );
    }
}"}

{"security_risk":"LOW","summary":"Create files.rs","command":"create","path":"/workspace/codebase/src/files.rs","file_text":"//! Recursive file discovery for paths passed to the CLI.
//!
//! Equivalent to `Runner.getAllFiles` / `Runner.dirFiles` in the original
//! implementation, including the "skip paths that don't exist" warning
//! and the same extension/ignore filtering pipeline.

use std::path::{Path, PathBuf};

use crate::ignore::IgnoreSet;

#[derive(Debug, Default, Clone)]
pub struct FileDiscoveryOptions {
    pub extensions: Vec<String>,
    pub ignore: IgnoreSet,
}

pub struct FileDiscovery {
    options: FileDiscoveryOptions,
}

impl FileDiscovery {
    pub fn new(options: FileDiscoveryOptions) -> Self {
        Self { options }
    }

    /// Walk every input path. Non-existent paths write a warning to stderr
    /// (unless silent) and are silently skipped — matching the upstream
    /// behavior.
    pub fn collect<P: AsRef<Path>>(
        &self,
        paths: &[P],
        silent: bool,
    ) -> Vec<PathBuf> {
        let mut out = Vec::new();
        for raw in paths {
            let p = raw.as_ref();
            match std::fs::metadata(p) {
                Ok(meta) => {
                    if meta.is_dir() {
                        self.walk(p, &mut out);
                    } else if self.should_include(p) {
                        out.push(p.to_path_buf());
                    }
                }
                Err(_) => {
                    if !silent {
                        eprintln!("Skipping path {} which does not exist.", p.display());
                    }
                }
            }
        }
        out.sort();
        out.dedup();
        out
    }

    fn walk(&self, dir: &Path, out: &mut Vec<PathBuf>) {
        let entries = match std::fs::read_dir(dir) {
            Ok(e) => e,
            Err(_) => return,
        };
        for entry in entries.flatten() {
            let name = entry.path();
            if self.options.ignore.should_ignore(&name) {
                continue;
            }
            let meta = match entry.file_type() {
                Ok(t) => t,
                Err(_) => continue,
            };
            if meta.is_dir() {
                self.walk(&name, out);
            } else if meta.is_file() && self.should_include(&name) {
                out.push(name);
            }
        }
    }

    fn should_include(&self, path: &Path) -> bool {
        if self.options.ignore.should_ignore(path) {
            return false;
        }
        if self.options.extensions.is_empty() {
            return true;
        }
        let ext = path
            .extension()
            .and_then(|e| e.to_str())
            .unwrap_or("")
            .to_lowercase();
        let ext_no_dot = ext.trim_start_matches('.');
        let normalized: Vec<String> = self
            .options
            .extensions
            .iter()
            .map(|e| e.trim_start_matches('.').to_lowercase())
            .collect();
        normalized.iter().any(|e| e == &ext_no_dot)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn includes_default_extension() {
        let dir = tempdir();
        std::fs::write(dir.path().join("a.js"), "x").unwrap();
        std::fs::write(dir.path().join("b.txt"), "x").unwrap();
        let opts = FileDiscoveryOptions {
            extensions: vec!["js".to_string()],
            ignore: IgnoreSet::new(),
        };
        let disc = FileDiscovery::new(opts);
        let files = disc.collect(&[dir.path().to_path_buf()], true);
        assert_eq!(files.len(), 1);
        assert!(files[0].ends_with("a.js"));
    }

    fn tempdir() -> tempfile::TempDir {
        tempfile::tempdir().unwrap()
    }
}"}

