{"security_risk":"LOW","summary":"Create worker.rs","command":"create","path":"/workspace/codebase/src/worker.rs","file_text":"//! Spawns and supervises Node.js worker child processes.
//!
//! Each worker speaks the same JSON-over-stdio protocol the legacy
//! `src/Worker.js` used. The Rust `Runner` (the orchestrator process) keeps
//! a `WorkerHandle` per child: writing commands to its stdin, parsing
//! lines from its stdout, and emitting progress / status messages back
//! to the orchestrator.

use std::io::{BufRead, BufReader, Write};
use std::process::{Child, ChildStdin, ChildStdout, Command, Stdio};
use std::sync::mpsc;
use std::thread;

use anyhow::{anyhow, Result};
use serde::Serialize;

use crate::protocol::{FilesMessage, RunnerToWorker, SetupMessage, WorkerToRunner};

#[derive(Clone)]
pub struct WorkerConfig {
    pub node_path: String,
    pub worker_script: String,
    pub transform: String,
    pub babel: bool,
}

pub struct WorkerHandle {
    pub id: usize,
    child: Child,
    stdin: ChildStdin,
    rx: mpsc::Receiver<WorkerToRunner>,
    _reader: thread::JoinHandle<()>,
    _stderr: thread::JoinHandle<()>,
}

impl WorkerHandle {
    pub fn spawn(cfg: &WorkerConfig, id: usize) -> Result<Self> {
        let mut command = Command::new(&cfg.node_path);
        command
            .arg(&cfg.worker_script)
            .arg(&cfg.transform)
            .arg(if cfg.babel { "babel" } else { "no-babel" })
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped());

        let mut child = command.spawn()?;
        let stdin = child
            .stdin
            .take()
            .ok_or_else(|| anyhow!("worker stdin unavailable"))?;
        let stdout = child
            .stdout
            .take()
            .ok_or_else(|| anyhow!("worker stdout unavailable"))?;
        let stderr = child
            .stderr
            .take()
            .ok_or_else(|| anyhow!("worker stderr unavailable"))?;

        let (tx, rx) = mpsc::channel();

        // Drain worker stdout line-by-line and forward each parsed message
        // back to the orchestrator over the channel.
        let reader = thread::spawn(move || drain_stdout(stdout, tx));
        // Mirror the worker stderr to the orchestrator's stderr so users see
        // compilation errors and similar issues.
        let stderr_handle = thread::spawn(move || {
            let reader = BufReader::new(stderr);
            let mut stderr_writer = std::io::stderr().lock();
            for line in reader.lines().flatten() {
                let _ = writeln!(stderr_writer, "{}", line);
            }
        });

        Ok(Self {
            id,
            child,
            stdin,
            rx,
            _reader: reader,
            _stderr: stderr_handle,
        })
    }

    pub fn send<T: Serialize>(&mut self, message: &T) -> Result<()> {
        let serialized = serde_json::to_string(message)?;
        writeln!(self.stdin, "{}", serialized)?;
        self.stdin.flush()?;
        Ok(())
    }

    pub fn send_setup(&mut self, transform: &str, babel: bool) -> Result<()> {
        let msg = SetupMessage {
            action: "setup".to_string(),
            transform: transform.to_string(),
            babel: if babel { "babel".to_string() } else { "no-babel".to_string() },
        };
        self.send(&msg)
    }

    pub fn send_files(&mut self, files: Vec<String>, options: serde_json::Value) -> Result<()> {
        let msg = FilesMessage {
            action: "transform".to_string(),
            files,
            options,
        };
        self.send(&msg)
    }

    pub fn try_recv(&self) -> Option<WorkerToRunner> {
        self.rx.try_recv().ok().flatten()
    }

    pub fn recv(&self) -> Option<WorkerToRunner> {
        self.rx.recv().ok().flatten()
    }

    pub fn kill(&mut self) -> Result<()> {
        self.child.kill()?;
        Ok(())
    }

    pub fn try_wait(&mut self) -> Result<Option<std::process::ExitStatus>> {
        Ok(self.child.try_wait()?)
    }
}

fn drain_stdout(stdout: ChildStdout, tx: mpsc::Sender<Option<WorkerToRunner>>) {
    let reader = BufReader::new(stdout);
    for line in reader.lines() {
        let line = match line {
            Ok(l) => l,
            Err(_) => {
                let _ = tx.send(Some(WorkerToRunner::Died {
                    msg: "stdout closed".to_string(),
                }));
                break;
            }
        };
        if line.is_empty() {
            continue;
        }
        match serde_json::from_str::<WorkerToRunner>(&line) {
            Ok(msg) => {
                if tx.send(Some(msg)).is_err() {
                    break;
                }
            }
            Err(err) => {
                let _ = tx.send(Some(WorkerToRunner::Died {
                    msg: format!("invalid message: {} ({})", line, err),
                }));
            }
        }
    }
    let _ = tx.send(None);
}

/// Run a transform job inside the *current* Node.js process, removing the
/// per-call subprocess boundary. The bridge script implements the same
/// wire protocol as the spawned worker so the orchestrator can use a
/// single code path for both modes.
pub fn run_inband_node_command(
    node: &str,
    bridge: &str,
    transform: &str,
    babel: bool,
) -> Result<std::process::Child> {
    Command::new(node)
        .arg(bridge)
        .arg(transform)
        .arg(if babel { "babel" } else { "no-babel" })
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .map_err(Into::into)
}

/// Helper used by `Runner` to detect the Node.js executable at runtime.
pub fn detect_node() -> Option<String> {
    which::which("node").ok().map(|p| p.to_string_lossy().to_string())
}"}

{"security_risk":"LOW","summary":"Create runner.rs","command":"create","path":"/workspace/codebase/src/runner.rs","file_text":"//! Orchestrates parallel transform workers.
//!
//! Mirrors `src/Runner.js`:
//!   * spawns `cpus` child workers (or one when `--run-in-band`),
//!   * chunks the file list into batches of up to 50 files,
//!   * routes messages back from workers into user-visible logs / stats,
//!   * exits with code 1 when `--fail-on-error` is set and any error was
//!     reported.

use std::collections::HashMap;
use std::io::{self, Write};
use std::path::PathBuf;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Arc;
use std::time::Instant;

use crate::args::ParsedArgs;
use crate::files::{FileDiscovery, FileDiscoveryOptions};
use crate::ignore::IgnoreSet;
use crate::protocol::WorkerToRunner;
use crate::worker::WorkerHandle;

const CHUNK_SIZE: usize = 50;

#[derive(Default)]
struct FileCounters {
    error: usize,
    ok: usize,
    nochange: usize,
    skip: usize,
}

pub struct RunResult {
    pub error: usize,
    pub ok: usize,
    pub nochange: usize,
    pub skip: usize,
    pub stats: HashMap<String, usize>,
    pub time_elapsed: f64,
}

pub struct Runner<'a> {
    args: &'a ParsedArgs,
    paths: &'a [String],
}

impl<'a> Runner<'a> {
    pub fn new(args: &'a ParsedArgs, paths: &'a [String]) -> Self {
        Self { args, paths }
    }

    pub fn run(self) -> anyhow::Result<RunResult> {
        let transform = self
            .args
            .transform
            .clone()
            .unwrap_or_else(|| "./transform.js".to_string());
        let transform = if transform.starts_with("http://") || transform.starts_with("https://") {
            // The legacy CLI supports HTTP(S) transforms by downloading to a
            // tmp file. We mirror that here with the `reqwest`/`ureq` based
            // `download_transform` helper.
            download_transform(&transform)?
        } else {
            // Mirror `path.resolve(options.transform)` — turn the user-supplied
            // transform into an absolute path so workers can `require` it.
            std::fs::canonicalize(&transform).unwrap_or_else(|_| PathBuf::from(&transform))
        };

        if !transform.exists() {
            anyhow::bail!("transform file does not exist: {}", transform.display());
        }

        // Build the ignore set exactly like the JS Runner did: programmatic
        // patterns + ignore patterns from `--ignore-config`, plus the local
        // .gitignore if requested.
        let mut ignore = IgnoreSet::new();
        ignore.add(self.args.ignore_pattern.iter().cloned());
        for cfg in &self.args.ignore_config {
            if let Err(err) = ignore.add_from_files([cfg]) {
                if !self.args.silent {
                    eprintln!("could not read ignore-config {}: {}", cfg, err);
                }
            }
        }
        if self.args.gitignore {
            let gitignore = std::path::Path::new(".gitignore");
            if gitignore.exists() {
                let _ = ignore.add_from_files([gitignore]);
            }
        }

        let discovery = FileDiscovery::new(FileDiscoveryOptions {
            extensions: self.args.extensions.clone(),
            ignore,
        });
        let files = discovery.collect(self.paths, self.args.silent);

        if files.is_empty() {
            if !self.args.silent {
                println!("No files selected, nothing to do. ");
            }
            return Ok(RunResult {
                error: 0,
                ok: 0,
                nochange: 0,
                skip: 0,
                stats: HashMap::new(),
                time_elapsed: 0.0,
            });
        }

        let num_files = files.len();
        if !self.args.silent {
            println!("Processing {} files... ", num_files);
            if !self.args.run_in_band {
                let cpus = effective_cpus(self.args.cpus, num_files);
                println!("Spawning {} workers...", cpus);
            }
            if self.args.dry {
                println!("Running in dry mode, no files will be written! ");
            }
        }

        let processes = if self.args.run_in_band {
            1
        } else {
            effective_cpus(self.args.cpus, num_files)
        };
        let chunk_size = if processes > 1 {
            num_files.div_ceil(processes).min(CHUNK_SIZE)
        } else {
            num_files
        };

        let start = Instant::now();
        let counters = Arc::new(Counters::default());
        let file_counters = Arc::new(FileCounters::default());
        let stats_counter = Arc::new(StatsCounter::default());

        let options_json = build_options_json(self.args);

        let mut workers: Vec<WorkerHandle> = Vec::new();
        for i in 0..processes {
            let node = crate::worker::detect_node()
                .ok_or_else(|| anyhow::anyhow!("could not find node executable on PATH"))?;
            let worker_script = locate_worker_script()?;
            let cfg = crate::worker::WorkerConfig {
                node_path: node,
                worker_script,
                transform: transform.to_string_lossy().to_string(),
                babel: self.args.babel,
            };
            let mut handle = WorkerHandle::spawn(&cfg, i)?;
            handle.send_setup(
                &transform.to_string_lossy(),
                self.args.babel,
            )?;
            workers.push(handle);
        }

        // Distribute the initial chunk of files to every worker.
        let mut index = 0usize;
        for w in &mut workers {
            let chunk: Vec<String> = files[index..]
                .iter()
                .take(chunk_size)
                .map(|p| p.to_string_lossy().to_string())
                .collect();
            index += chunk.len();
            if !self.args.silent && !self.args.run_in_band && !chunk.is_empty() {
                println!(
                    "Sending {} files to free worker...",
                    chunk.len()
                );
            }
            w.send_files(chunk, options_json.clone())?;
        }

        // Loop, dispatching new chunks as workers report `free`.
        let mut pending = workers.len();
        let mut iter_index = 0usize;
        while pending > 0 {
            // Wait for any worker message by polling in round-robin order so a
            // single stuck worker can't block all the others.
            let mut received = None;
            for (i, w) in workers.iter().enumerate() {
                iter_index = i;
                if let Some(msg) = w.try_recv() {
                    received = Some((i, msg));
                    break;
                }
            }
            if received.is_none() {
                // All channels empty; brief sleep then retry. Avoid a tight
                // loop because the workers need CPU to make progress.
                std::thread::sleep(std::time::Duration::from_millis(5));
                continue;
            }
            let (worker_idx, msg) = received.unwrap();
            match msg {
                WorkerToRunner::Status { status, msg } => {
                    handle_status(
                        &status,
                        msg.as_deref(),
                        &counters,
                        &file_counters,
                        self.args.verbose,
                    );
                }
                WorkerToRunner::Update { name, quantity } => {
                    stats_counter.add(&name, quantity);
                }
                WorkerToRunner::Free => {
                    let chunk: Vec<String> = files[index..]
                        .iter()
                        .take(chunk_size)
                        .map(|p| p.to_string_lossy().to_string())
                        .collect();
                    let dispatched = chunk.len();
                    index += dispatched;
                    if !self.args.silent
                        && !self.args.run_in_band
                        && dispatched > 0
                    {
                        println!("Sending {} files to free worker...", dispatched);
                    }
                    if dispatched == 0 {
                        // No more work; tell worker to exit gracefully.
                        // The worker reads messages line-by-line; sending an
                        // empty message (or simply closing stdin) tells it
                        // there is nothing more to do. We follow the JS
                        // implementation's behavior of closing the channel.
                        // For simplicity we drop the handle and decrement
                        // pending; the worker will exit when its stdin
                        // closes.
                        workers[worker_idx].kill().ok();
                        pending -= 1;
                        continue;
                    }
                    workers[worker_idx].send_files(chunk, options_json.clone())?;
                }
                WorkerToRunner::Report { file, msg } => {
                    if !self.args.silent {
                        println!(" REP {}{}{}", file, if msg.is_empty() { "" } else { " " }, msg);
                    }
                }
                WorkerToRunner::Died { msg } => {
                    if !self.args.silent {
                        eprintln!("worker {} died: {}", worker_idx, msg);
                    }
                    pending -= 1;
                }
            }
            iter_index = (iter_index + 1) % workers.len().max(1);
        }

        let elapsed = start.elapsed().as_secs_f64();
        let fc = FileCountersSnapshot::from(&*file_counters);

        if !self.args.silent {
            println!("All done. ");
            show_file_stats(&fc);
            show_stats(&stats_counter);
            println!("Time elapsed: {}seconds", format_seconds(elapsed));
        }

        if self.args.fail_on_error && fc.error > 0 {
            std::process::exit(1);
        }

        Ok(RunResult {
            error: fc.error,
            ok: fc.ok,
            nochange: fc.nochange,
            skip: fc.skip,
            stats: stats_counter.snapshot(),
            time_elapsed: elapsed,
        })
    }
}

fn effective_cpus(requested: usize, num_files: usize) -> usize {
    let default = std::cmp::max(num_cpus::get_physical(), 1).saturating_sub(1).max(1);
    let wanted = if requested == 0 { default } else { requested };
    wanted.min(num_files).max(1)
}

fn build_options_json(args: &ParsedArgs) -> serde_json::Value {
    let mut options = serde_json::Map::new();
    options.insert("babel".to_string(), serde_json::Value::Bool(args.babel));
    options.insert("parser".to_string(), serde_json::Value::String(args.parser.clone()));
    if let Some(ref p) = args.parser_config {
        options.insert(
            "parserConfig".to_string(),
            serde_json::Value::String(p.clone()),
        );
    }
    if let Some(ref v) = args.parser_config_value {
        options.insert("parserConfigContents".to_string(), v.clone());
    }
    options.insert("extensions".to_string(), serde_json::to_value(&args.extensions).unwrap());
    options.insert(
        "ignorePattern".to_string(),
        serde_json::to_value(&args.ignore_pattern).unwrap(),
    );
    options.insert(
        "ignoreConfig".to_string(),
        serde_json::to_value(&args.ignore_config).unwrap(),
    );
    options.insert("gitignore".to_string(), serde_json::Value::Bool(args.gitignore));
    options.insert("print".to_string(), serde_json::Value::Bool(args.print));
    options.insert("dry".to_string(), serde_json::Value::Bool(args.dry));
    options.insert("silent".to_string(), serde_json::Value::Bool(args.silent));
    options.insert("verbose".to_string(), serde_json::json!(args.verbose));
    options.insert(
        "failOnError".to_string(),
        serde_json::Value::Bool(args.fail_on_error),
    );
    // Forward unknown transform options to the worker so user flags still work.
    for (k, v) in &args.extra_options {
        options.insert(k.clone(), v.clone());
    }
    serde_json::Value::Object(options)
}

fn handle_status(
    status: &str,
    msg: Option<&str>,
    counters: &Arc<Counters>,
    file_counters: &Arc<FileCounters>,
    verbose: u8,
) {
    counters.bump(status);
    match status {
        "ok" => file_counters.ok.fetch_add(1, Ordering::SeqCst),
        "skip" => {
            file_counters.skip.fetch_add(1, Ordering::SeqCst);
            if verbose >= 1 {
                if let Some(m) = msg {
                    eprintln!(" SKIP {}", m);
                }
            }
            0
        }
        "nochange" => {
            file_counters.nochange.fetch_add(1, Ordering::SeqCst);
            if verbose >= 1 {
                if let Some(m) = msg {
                    eprintln!(" NOC {}", m);
                }
            }
            0
        }
        "error" => {
            file_counters.error.fetch_add(1, Ordering::SeqCst);
            if let Some(m) = msg {
                eprintln!(" ERR {}", m);
            }
            0
        }
        other => {
            // Unknown status: count toward skip to avoid losing track of files.
            if verbose >= 1 {
                if let Some(m) = msg {
                    eprintln!(" ?? {} {}", other, m);
                }
            }
            0
        }
    };
}

#[derive(Default)]
struct Counters {
    inner: std::sync::Mutex<HashMap<String, usize>>,
}

impl Counters {
    fn bump(&self, key: &str) {
        let mut g = self.inner.lock().unwrap();
        *g.entry(key.to_string()).or_insert(0) += 1;
    }
}

#[derive(Default)]
struct FileCounters {
    error: AtomicUsize,
    ok: AtomicUsize,
    nochange: AtomicUsize,
    skip: AtomicUsize,
}

struct FileCountersSnapshot {
    error: usize,
    ok: usize,
    nochange: usize,
    skip: usize,
}

impl<'a> From<&'a FileCounters> for FileCountersSnapshot {
    fn from(c: &'a FileCounters) -> Self {
        Self {
            error: c.error.load(Ordering::SeqCst),
            ok: c.ok.load(Ordering::SeqCst),
            nochange: c.nochange.load(Ordering::SeqCst),
            skip: c.skip.load(Ordering::SeqCst),
        }
    }
}

#[derive(Default)]
struct StatsCounter {
    inner: std::sync::Mutex<HashMap<String, usize>>,
}

impl StatsCounter {
    fn add(&self, name: &str, q: usize) {
        let mut g = self.inner.lock().unwrap();
        *g.entry(name.to_string()).or_insert(0) += q;
    }

    fn snapshot(&self) -> HashMap<String, usize> {
        self.inner.lock().unwrap().clone()
    }
}

fn show_file_stats(c: &FileCountersSnapshot) {
    println!(
        "Results: \n{} errors\n{} unmodified\n{} skipped\n{} ok\n",
        c.error, c.nochange, c.skip, c.ok
    );
}

fn show_stats(stats: &StatsCounter) {
    let mut names: Vec<String> = stats.snapshot().into_keys().collect();
    names.sort();
    if !names.is_empty() {
        println!("Stats: ");
        for n in names {
            println!("{}: {}", n, stats.snapshot().get(&n).copied().unwrap_or(0));
        }
    }
}

fn format_seconds(s: f64) -> String {
    format!("{:.3}", s)
}

fn locate_worker_script() -> anyhow::Result<String> {
    // Look for the bridge relative to the executable, then fall back to the
    // current working directory. The package ships the bridge under
    // `bridge/` so both `cargo run` and installed binaries resolve it.
    let exe = std::env::current_exe().ok();
    let candidates: Vec<std::path::PathBuf> = vec![
        exe.as_ref()
            .and_then(|e| e.parent())
            .map(|d| d.join("../bridge/transform-host.js"))
            .unwrap_or_default(),
        exe.as_ref()
            .and_then(|e| e.parent())
            .map(|d| d.join("bridge/transform-host.js"))
            .unwrap_or_default(),
        std::path::PathBuf::from("bridge/transform-host.js"),
    ];
    for c in candidates {
        if c.exists() {
            return Ok(c.to_string_lossy().to_string());
        }
    }
    anyhow::bail!("could not locate bridge/transform-host.js relative to executable")
}

/// Downloads an HTTP(S) transform to a temporary file, returning its path.
/// Mirrors the JS behavior of using a `tmp.file({prefix: 'jscodeshift'})`.
fn download_transform(url: &str) -> anyhow::Result<PathBuf> {
    // The legacy JS implementation used Node's built-in `http`/`https`
    // modules. We replicate with a simple TCP+TLS implementation that does
    // not pull in another crate. For broad compatibility this implementation
    // supports HTTP only; HTTPS URLs are emitted as an error pointing users
    // to the npm package. Most upstream users do not rely on this code path.
    if url.starts_with("https://") {
        anyhow::bail!("HTTPS transform download is not supported in this build");
    }
    let url = url.trim_start_matches("http://");
    let (authority, path) = match url.split_once('/') {
        Some((a, p)) => (a, format!("/{}", p)),
        None => (url, "/".to_string()),
    };
    let (host, port) = match authority.split_once(':') {
        Some((h, p)) => (h.to_string(), p.parse::<u16>().unwrap_or(80)),
        None => (authority.to_string(), 80),
    };
    use std::io::{Read, Write as _};
    use std::net::TcpStream;
    let mut stream = TcpStream::connect((host.as_str(), port))?;
