/// keeping the Rust binary free of fragile filesystem probing.
fn detect_bridge_versions() -> Option<String> {
    let node = which::which("node").ok()?;
    let candidates = [
        std::path::PathBuf::from("bridge/print-versions.js"),
        std::path::PathBuf::from("../bridge/print-versions.js"),
    ];
    for c in &candidates {
        if !c.exists() {
            continue;
