/// Downloads an HTTP(S) transform to a temporary file, returning its path.
/// Mirrors the JS behavior of using a `tmp.file({prefix: 'jscodeshift'})`.
fn download_transform(url: &str) -> anyhow::Result<PathBuf> {
    if url.starts_with("https://") {
        anyhow::bail!("HTTPS transform download is not supported in this build");
    }
    let url = url.trim_start_matches("http://");
    let (authority, path) = match url.split_once('/') {
        Some((a, p)) => (a, format!("/{}", p)),
        None => (url, "/".to_string()),
    };
    let (host, port) = match authority.split_once(':') {
        Some((h, p)) => (h.to_string(), p.parse::<u16>().unwrap_or(80)),
        None => (authority.to_string(), 80),
    };
    use std::io::Write;
    use std::net::TcpStream;
    let mut stream = TcpStream::connect((host.as_str(), port))?;
    write!(
        stream,
        "GET {} HTTP/1.0\r\nHost: {}\r\nConnection: close\r\n\r\n",
        path, host
    )?;
    let mut raw = Vec::new();
    stream.read_to_end(&mut raw)?;
    let body_start = raw
        .windows(4)
        .position(|w| w == b"\r\n\r\n")
        .map(|i| i + 4)
        .unwrap_or(0);
    let body = &raw[body_start..];
    let tmp = std::env::temp_dir().join(format!("jscodeshift-{}", std::process::id()));
    std::fs::write(&tmp, body)?;
    Ok(tmp)
}

/// Reads the stdin file-list into a vector of paths. Used when the user
/// passes `--stdin`.
pub fn read_stdin_paths() -> anyhow::Result<Vec<String>> {
    let mut buf = String::new();
    io::stdin().read_to_string(&mut buf)?;
    Ok(buf
        .lines()
        .map(|s| s.trim().to_string())
        .filter(|s| !s.is_empty())
        .collect())
}"}

