 *
 * Worker bridge spawned by the Rust CLI.
 *
 * This file is the only JavaScript that remains in the runtime: the Rust
 * orchestrator spawns one Node.js process per worker, this process loads
 * and applies a user-supplied transform, and reports results back over
 * stdin/stdout using the original JSON message protocol.
 *
 * Protocol (line-delimited JSON over stdio):
 *   runner -> worker:  {action:"setup", transform, babel}
 *                     {action:"transform", files, options}
 *   worker -> runner:  {action:"status", status, msg}
 *                     {action:"update", name, quantity}
 *                     {action:"report", file, msg}
 *                     {action:"free"}
 *
 * It intentionally stays close to the original `src/Worker.js` so the
 * upstream transforms keep working without changes: the same arguments,
 * the same jscodeshift API, and the same writeFileAtomic semantics.
 */

'use strict';

const fs = require('graceful-fs');
const async = require('neo-async');
const writeFileAtomic = require('write-file-atomic');
const { DEFAULT_EXTENSIONS } = require('@babel/core');

const jscodeshift = require('./jscodeshift-api');
const getParser = require('./getParser');

let presetEnv;
try {
  presetEnv = require('@babel/preset-env');
} catch (_) {}

let transform;
let parserFromTransform;

setup(process.argv[2], process.argv[3]);

let buffer = '';
process.stdin.setEncoding('utf8');
process.stdin.on('data', chunk => {
  buffer += chunk;
  let newline;
  while ((newline = buffer.indexOf('\n')) !== -1) {
    const line = buffer.slice(0, newline);
    buffer = buffer.slice(newline + 1);
    if (line.trim().length === 0) continue;
    try {
      handle(JSON.parse(line));
    } catch (err) {
      sendStatus('error', '', 'Bridge protocol error: ' + err.message);
    }
  }
});
process.stdin.on('end', () => process.exit(0));

function setup(tr, babel) {
  if (babel === 'babel') {
    const presets = [];
    if (presetEnv) {
      presets.push([
        presetEnv.default,
        { targets: { node: true } },
      ]);
    }
    presets.push(
      /\.tsx?$/.test(tr)
        ? require('@babel/preset-typescript').default
        : require('@babel/preset-flow').default
    );

    require('@babel/register')({
      configFile: false,
      babelrc: false,
      presets,
      plugins: [
        require('@babel/plugin-transform-class-properties').default,
        require('@babel/plugin-transform-nullish-coalescing-operator').default,
        require('@babel/plugin-transform-optional-chaining').default,
        require('@babel/plugin-transform-modules-commonjs').default,
        require('@babel/plugin-transform-private-methods').default,
      ],
      extensions: [...DEFAULT_EXTENSIONS, '.ts', '.tsx'],
      ignore: [
        /@babel\/parser/,
        /\/flow-parser\//,
        /\/recast\//,
        /\/ast-types\//,
      ],
    });
  }

  const module = require(tr);
  transform = typeof module.default === 'function'
    ? module.default
    : module;
  if (module.parser) {
    parserFromTransform = typeof module.parser === 'string'
      ? getParser(module.parser)
      : module.parser;
  }
}

function prepareJscodeshift(options) {
  const parser = parserFromTransform ||
    getParser(options.parser, options.parserConfig);
  return jscodeshift.withParser(parser);
}

function handle(message) {
  switch (message.action) {
    case 'setup':
      // Setup already ran in `setup()` at startup; nothing more to do.
      return;
    case 'transform':
      run(message);
      return;
    default:
      sendStatus('error', '', 'Unknown action: ' + message.action);
      return;
  }
}

function run(data) {
  const files = data.files || [];
  const options = data.options || {};
  if (!files.length) {
    sendFree();
    return;
  }
  async.each(
    files,
    function (file, callback) {
      fs.readFile(file, async function (err, source) {
        if (err) {
          sendStatus('error', file, 'File error: ' + err);
          callback();
          return;
        }
        source = source.toString();
        try {
          const j = prepareJscodeshift(options);
          const out = await transform(
            { path: file, source: source },
            {
              j: j,
              jscodeshift: j,
              stats: options.dry ? stats : empty,
              report: msg => report(file, msg),
            },
            options
          );
          if (!out || out === source) {
            sendStatus(out ? 'nochange' : 'skip', file);
            callback();
            return;
          }
          if (options.print) {
            process.stdout.write(out + '\n');
          }
          if (!options.dry) {
            writeFileAtomic(file, out, function (err) {
              if (err) {
                sendStatus('error', file, 'File writer error: ' + err);
              } else {
                sendStatus('ok', file);
              }
              callback();
            });
          } else {
            sendStatus('ok', file);
            callback();
          }
        } catch (err) {
          sendStatus(
            'error',
            file,
            'Transformation error (' + String(err.message).replace(/\n/g, ' ') + ')\n' +
              trimStackTrace(err.stack)
          );
          callback();
        }
      });
    },
    function (err) {
      if (err) {
        sendStatus('error', '', 'This should never be shown!');
      }
      sendFree();
    }
  );
}

function trimStackTrace(trace) {
  if (!trace) return '';
  const lines = trace.split('\n');
  const result = [];
  lines.every(function (line) {
    if (line.indexOf(__filename) === -1) {
      result.push(line);
      return true;
    }
  });
  return result.join('\n');
}

function empty() {}

function stats(name, quantity) {
  quantity = typeof quantity !== 'number' ? 1 : quantity;
  process.stdout.write(
    JSON.stringify({ action: 'update', name, quantity }) + '\n'
  );
}

function sendStatus(status, file, msg) {
  const payload = msg ? file + ' ' + msg : file;
  process.stdout.write(
    JSON.stringify({ action: 'status', status, msg: payload }) + '\n'
  );
}

function report(file, msg) {
  process.stdout.write(
    JSON.stringify({ action: 'report', file, msg }) + '\n'
  );
}

function sendFree() {
  process.stdout.write(JSON.stringify({ action: 'free' }) + '\n');
}"}

