  path.resolve(__dirname, '..', 'src', 'core'),
  path.resolve(__dirname, 'src', 'core'),
];

let core;
for (const c of candidates) {
  try {
    core = require(c);
    break;
  } catch (_) {}
}
if (!core) {
  throw new Error('jscodeshift bridge: could not locate src/core');
}

module.exports = core;
module.exports.core = core;
